/**
 * Sentinel Sum
 * node starter/index.js
 */

const readline = require("node:readline");

function main() {
  const rl = readline.createInterface({ input: process.stdin });
  let sum = 0;
  let current = null;
  let reading = true;


  rl.on("line", (line) => {
current = Number(line.trim());


while(reading){
sum += Number(line.trim());
reading = (current!=0);
break;
}
if (!reading){
console.log("Sum:", sum);
}
    // TODO: while-loop style accumulation until sentinel 0
    rl.close();
  });
}

main();

/**
 * Sentinel Sum
 * node starter/index.js
 */

const readline = require("node:readline");

function main() {
  const rl = readline.createInterface({ input: process.stdin });
  let sum = 0;
  let current = null;
  let reading = true;


  rl.on("line", (line) => {
current = Number(line.trim());

if (!Number.isInteger(current)){
console.log("ERROR: invalid number") ;
rl.close;
return;
}


while(reading){
sum += Number(line.trim());
reading = (current!=0);
break;
}
if (!reading){
console.log("Sum:", sum);
}
    // TODO: while-loop style accumulation until sentinel 0
    rl.close();
  });
}

main();
